 "content": "from collections import Counter


def transform(grid):
    """Repeat the non-background pattern across tiles separated by solid lines."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != background]
    cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]
    out = [row[:] for row in grid]

    def segments(size, dividers):
        result = []
        start = 0
        for d in dividers:
            result.append((start, d))
            start = d + 1
        result.append((start, size))
        return [(a, b) for a, b in result if a < b]

    if rows:
        tiles = segments(h, rows)
        max_len = max(b - a for a, b in tiles)
        for local_r in range(max_len):
            for c in range(w):
                values = [grid[a + local_r][c] for a, b in tiles if a + local_r < b and grid[a + local_r][c] != background]
                if not values:
                    continue
                value = Counter(values).most_common(1)[0][0]
                for a, b in tiles:
                    r = a + local_r
                    if r < b and out[r][c] == background:
                        out[r][c] = value
    elif cols:
        tiles = segments(w, cols)
        max_len = max(b - a for a, b in tiles)
        for local_c in range(max_len):
            for r in range(h):
                values = [grid[r][a + local_c] for a, b in tiles if a + local_c < b and grid[r][a + local_c] != background]
                if not values:
                    continue
                value = Counter(values).most_common(1)[0][0]
                for a, b in tiles:
                    c = a + local_c
                    if c < b and out[r][c] == background:
                        out[r][c] = value
    return out
